    private void sendSmartAiRequest(
            @NonNull String question,
            @NonNull FirebaseStudyTutorClient.TutorRequest tutorRequest,
            @NonNull AdaptiveLearningLevelResolver.AdaptiveLevel adaptiveLevel,
            @NonNull StudentMisconceptionDetector.Detection misconception,
            int requestGeneration,
            @Nullable Bitmap questionBitmap
    ) {
        final boolean originalImageAttached =
                questionBitmap != null;

        firebaseStudyTutorClient.askQuestionWithResult(
                tutorRequest,
                questionBitmap,
                new FirebaseStudyTutorClient.TutorResultCallback() {

                    @Override
                    public void onSuccess(
                            @NonNull SmartTutorAnswerResult result
                    ) {
                        recycleAiQuestionBitmap(
                                questionBitmap
                        );

                        if (!isCurrentAiAnswerRequest(
                                requestGeneration
                        )) {
                            return;
                        }

                        binding.progressQuestionImageOcr.setVisibility(
                                View.GONE
                        );

                        finishSmartAiLoadingState();

                        new StudentKnowledgeGraphStore(AskStudySaathiActivity.this)
                                .recordAnswer(
                                        activeStudentProfile.getProfileId(),
                                        selectedSubjectName,
                                        selectedChapter == null
                                                ? "General"
                                                : selectedChapter.getDisplayTitle(),
                                        question,
                                        result
                                );
                        new StudentKnowledgeGraphStore(AskStudySaathiActivity.this)
                                .recordMisconceptionReview(
                                        activeStudentProfile.getProfileId(),
                                        selectedSubjectName,
                                        selectedChapter == null ? "General"
                                                : selectedChapter.getDisplayTitle(),
                                        question,
                                        misconception);

                        if (recommendedRevisionSession
                                && !recommendedRevisionCompletionRecorded) {
                            new RecommendedRevisionProgressStore(
                                    AskStudySaathiActivity.this).recordCompleted(
                                    selectedSubjectName,
                                    selectedChapter == null ? prefillChapterTitle
                                            : selectedChapter.getDisplayTitle());
                            recommendedRevisionCompletionRecorded = true;
                        }

                        showCompletedAnswer(
                                question,
                                "üéØ " + adaptiveLevel.getDisplayLabel() + "\n\n"
                                        + (misconception.shouldReview()
                                        ? "üß≠ " + misconception.getDisplayLabel() + "\n\n" : "")
                                        + result.buildDisplayAnswerText()
                        );

                        if (originalImageAttached
                                && selectedQuestionImageUri != null) {

                            binding.textQuestionImageStatus.setText(
                                    "Original photo ‡§î‡§∞ corrected text ‡§¶‡•ã‡§®‡•ã‡§Ç ‡§∏‡•á Smart AI answer ‡§§‡•à‡§Ø‡§æ‡§∞ ‡§π‡•Å‡§Ü‡•§"
                            );
                        }

                        saveDoubtHistory(
                                question,
                                "üéØ " + adaptiveLevel.getDisplayLabel() + "\n\n"
                                        + (misconception.shouldReview()
                                        ? "üß≠ " + misconception.getDisplayLabel() + "\n\n" : "")
                                        + result.buildDisplayAnswerText()
                        );

                        Snackbar.make(
                                binding.getRoot(),
                                originalImageAttached
                                        ? "Photo ‡§¶‡•á‡§ñ‡§ï‡§∞ Smart AI answer ‡§§‡•à‡§Ø‡§æ‡§∞ ‡§π‡•à‡•§"
                                        : "Smart AI answer ‡§§‡•à‡§Ø‡§æ‡§∞ ‡§π‡•à‡•§",
                                Snackbar.LENGTH_SHORT
                        ).show();
                    }

                    @Override
                    public void onError(
                            @NonNull Throwable throwable
                    ) {
                        recycleAiQuestionBitmap(
                                questionBitmap
                        );

                        if (!isCurrentAiAnswerRequest(
                                requestGeneration
                        )) {
                            return;
                        }

                        Log.e(
                                LOG_TAG,
                                "Firebase Smart AI request failed.",
                                throwable
                        );

                        binding.progressQuestionImageOcr.setVisibility(
                                View.GONE
                        );

                        finishSmartAiLoadingState();

                        showOfflineFallbackAnswer(
                                question,
                                throwable,
                                originalImageAttached
                        );
                    }
                }
        );
    }

    private void recycleAiQuestionBitmap(
            @Nullable Bitmap bitmap
    ) {
        if (bitmap == null
                || bitmap.isRecycled()) {

            return;
        }

        bitmap.recycle();
    }

    private boolean isCurrentAiAnswerRequest(
            int requestGeneration
    ) {
        return isActivityAvailable()
                && aiAnswerRequestInProgress
                && requestGeneration
                == aiAnswerRequestGeneration;
    }

